(kg,lb,sp,v)=>{
  const RER=70*Math.pow(kg,0.75), cup=(v.kcal>0?v.kcal:null);
  const R=x=>Math.round(x), R1=x=>Math.round(x*10)/10;
  const per=x=>cup?R1(x/cup):"";
  const out=[];
  const r1=[{v:"Resting Energy Requirement = 70 * Weight(kg)^0.75",c:"ind"},
            "RER =",{v:R(RER),c:"n"},"kcal/day"]; r1.plain=true; out.push(r1);
  const r2=[{v:"Maintenance ER = k * ER   (k values from Merk and VIN).",c:"ind"}];
  r2.plain=true; out.push(r2);
  const r3=["Water Intake  (normal = 1 ml per kcal):",
            {v:"= "+R(RER)+" ml",c:"n"},{v:"= "+R1(RER/236.6)+" cups",c:"n"}];
  r3.plain=true; out.push(r3);
  const r4=["pu/pd \u2261 over 100 ml/kg/day",
            {v:"= "+R(kg*100)+" ml",c:"n"},{v:"= "+R1(kg*100/236.6)+" cups",c:"n"}];
  r4.plain=true; out.push(r4);
  out.push({split:true});
  if(sp==="dog"){
    out.push({cols:["Condition",{v:"k Dog",c:"k"},"kcal/day","# cup/can","Water (cups/day)"]});
    const T=[["Typical Neutered Pet",1.6],{h:"Weight management"},["Wt loss (overweight)",1],
      ["Obese Prone",1.4],["Wt Gain (neutered)",2],["Wt Gain (intact)",2.2],
      {h:"Working"},["Light",2],["Moderate",3],["Heavy",6],
      {h:"Typical Pet"},["Intact",1.8],["Neutered",1.6],["Obese Prone",1.4],["Critical Care",1],
      {h:"Healthy Puppies"},["< 16 weeks",3],["> 16 weeks",2],
      {h:"Reproduction"},["Late gestation",3]];
    for(const t of T){
      if(t.h){out.push(t);continue;}
      const kc=RER*t[1];
      out.push([t[0],{v:t[1],c:"k"},{v:R(kc),c:"n"},{v:per(kc),c:"n"},
                {v:R1(kc/236)+" +- "+R1(kc/236/5),c:"n"}]);}
  }else{
    out.push({cols:["Condition",{v:"k Cat",c:"k"},"MER","# cups/can"]});
    const T=[{h:"Weight management"},["Wt loss (overweight)",0.8],["Obese Prone",1],
      ["Wt Gain (neutered)",1.47],["Wt Gain (intact)",1.7],
      {h:"Working"},["Light/Active",1.6],
      {h:"Typical Pet"},["Intact",1.4],["Neutered",1.2],["Obese Prone",1],["Critical Care",1],
      {h:"Healthy Kittens"},["< 16 weeks",2.5],["> 16 weeks",2.5],
      {h:"Reproduction"},["Late gestation","unknown"]];
    for(const t of T){
      if(t.h){out.push(t);continue;}
      if(typeof t[1]!=="number"){out.push([t[0],{v:t[1],c:"k"}]);continue;}
      const kc=RER*t[1];
      out.push([t[0],{v:t[1],c:"k"},{v:R(kc),c:"n"},{v:per(kc),c:"n"}]);}
  }
  return out;}

(kg,lb,sp,v)=>{
  const RER=70*Math.pow(kg,0.75), R=x=>Math.round(x), R2=x=>Math.round(x*100)/100;
  const n=Math.round(v.n), wk=Math.round(v.week);
  const out=[];
  if(sp==="dog"){
    const N={1:24,2:48,3:72,4:96,5:108,6:120,7:132,8:144}, L={1:0.75,2:0.95,3:1.1,4:1.2};
    const nn=N[Math.min(Math.max(n,1),8)], ll=L[Math.min(Math.max(wk,1),4)];
    out.push(["Dog","145/70 * RER + (n * BW * L)"]);
    out.push(["n =",nn,"(look-up table depends on # in litter)"]);
    out.push(["L =",ll,"(look-up table depends on age of pups/kittens)"]);
    const cal=145/70*RER+nn*kg*ll, reg=RER*1.8;
    out.push(["Dog:",R(cal),"cal/day"]);
    out.push(["Reg MER",R2(reg),"Increase feeding by",R2(cal/reg)]);
  }else{
    const nn=n<3?18:(n<=4?60:70), L={1:0.9,2:0.9,3:1.2,4:1.2,5:1.1,6:1,7:0.8};
    const ll=L[Math.min(Math.max(wk,1),7)];
    out.push(["Cat","100 * BW ^.67 + (n * BW * L)"]);
    out.push(["n =",nn,"(look-up table depends on # in litter)"]);
    out.push(["L =",ll,"(look-up table depends on age of pups/kittens)"]);
    const cal=100*Math.pow(kg,2/3)+nn*kg*ll, reg=RER*1.4;
    out.push(["Cat",R(cal),"cal/day"]);
    out.push(["Reg MER",R2(reg),"Increase feeding by",R2(cal/reg)]);
  }
  return out;}

(kg,lb,sp,v)=>{
  const na=v.na, glu=v.glu, bun=v.bun;
  if(!(na>0&&glu>0))return[["Enter Na and Glucose."]];
  const R=x=>Math.round(x);
  const corr=1.6*((glu-100)/100)+na;
  const out=[];
  out.push(["Na",na]);
  out.push(["Corrected Na",R(corr),"Na + (Glucose-100)/100*1.6"]);
  out.push(["Glucose",glu]);
  out.push(["BUN",bun>0?bun:""]);
  if(bun>0)out.push(["Calculated Osmolality:",R(2*corr+glu/18+bun/2.8),"2(Na+) + [glucose/18] + [BUN/2.8]"]);
  out.push(["Calculated Osmolality:",R(2*corr+glu/18),"2(Na) + Glucose/18"]);
  out.push(["Normal osmolality for dog = 280 to 310, cat = 180 to 310"]);
  out.push(["Water Dep test: d/c if Na > 165 or osmolality > 350"]);
  return out;}

(kg,lb,sp,v)=>{
  const w0=v.w0>0?v.w0:lb, i0=v.i0;
  const R1=x=>Math.round(x*10)/10, R2=x=>Math.round(x*100)/100;
  const out=[];
  out.push(["Initial Weight (Day 0)",R1(w0),"lbs"]);
  if(i0>0)out.push(["Initial Water Intake (Day 0)",i0,"cups/day"]);
  out.push({h:"End if"});
  out.push(["SpG  >",1.025]);
  out.push(["5 % weight loss, weight <=",R1(w0*0.9),"lb"]);
  out.push(["Water intake <= 60/ml/kg/day",R1(w0/2.2*60/236),"cups/day"]);
  out.push(["Na >",165]);
  out.push(["Osmolality >","350 (use table above)"]);
  out.push({h:"Gradual Water Dep Test"});
  out.push(["Measure water intake daily 3-5 days for average"]);
  out.push(["Weigh, check SpG on day 1 before water deprivation"]);
  out.push(["Each AM:  check weight, SpG & Na"]);
  out.push(["Reduce water  by 5 to 10% each day",i0>0?R2(i0/20):"","c/day (= 5%)"]);
  out.push(["If the patient becomes 5% dehydrated or loses 5% body weight, empty the bladder and check USG."]);
  out.push(["Administer DDAVP at 4 drops of 100 \u00b5g/mL solution either intranasally or into the conjunctival sac."]);
  out.push(["Hospitalize the patient and check USG in 3 hours.8 If USG is >1.025, the diagnosis is CDI. If USG is <1.025, NDI is the most likely diagnosis"]);
  out.push(["(From VIN DI page:)","https://www.vin.com/members/cms/project/defaultadv1.aspx?pid=607&id=4954112"]);
  return out;}
